1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const survivesWithNeighborCount = (count: number): boolean =>
12	  count === 2 || count === 3;
13	
14	const isBornWithNeighborCount = (count: number): boolean => count === 3;
15	
16	const neighborsOf = ([x, y]: Cell): Cell[] =>
17	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
18	
19	const uniqueCells = (cells: Cell[]): Cell[] =>
20	  [...new Map(cells.map((c) => [cellKey(c), c])).values()];
21	
22	const cellsToEvaluate = (aliveCells: Cell[]): Cell[] =>
23	  uniqueCells([...aliveCells, ...aliveCells.flatMap(neighborsOf)]);
24	
25	export function nextGeneration(cells: Cell[]): Cell[] {
26	  const aliveKeys = new Set(cells.map(cellKey));
27	  const isAlive = (cell: Cell): boolean => aliveKeys.has(cellKey(cell));
28	  const aliveNeighborCount = (cell: Cell): number =>
29	    neighborsOf(cell).filter(isAlive).length;
30	  const willBeAlive = (cell: Cell): boolean => {
31	    const count = aliveNeighborCount(cell);
32	    return isAlive(cell)
33	      ? survivesWithNeighborCount(count)
34	      : isBornWithNeighborCount(count);
35	  };
36	
37	  return cellsToEvaluate(cells).filter(willBeAlive);
38	}
